const fastify = require('fastify')({ logger: true });
const fs = require('fs');
const path = require('path');

const SONGS_DIRECTORY = '/var/songs';

fastify.post('/download', async (request, reply) => {
  const { filename } = request.body;

  if (!filename || typeof filename !== 'string') {
    return reply.status(400).send({ error: 'Invalid input' });
  }

  const filePath = path.join(SONGS_DIRECTORY, filename);

  try {
    await fs.promises.access(filePath); // Check if file exists
    reply.type('audio/mpeg');
    const readStream = fs.createReadStream(filePath);
    return reply.send(readStream);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return reply.status(404).send({ error: 'File does not exist' });
    }
    return reply.status(500).send({ error: 'Internal Server Error' });
  }
});

const start = async () => {
  try {
    await fastify.listen({ port: 5000, host: '0.0.0.0' });
    fastify.log.info(`Server listening on http://0.0.0.0:5000`);
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
};

start();
</CODE>
